package dev.createpolymer.kinetics.belt;

import net.minecraft.core.Direction;
import net.minecraft.core.Direction.AxisDirection;

/**
 * How a belt's moving surface is shown to a vanilla client.
 * <p>
 * Create scrolls the belt texture by shifting UVs every frame, which needs a client mod. Here the belt texture
 * is shown as a vertical animation strip: every frame is the texture shifted by {@code k} rows, each shown for
 * {@code f} ticks, so the surface moves {@code k / f} texture rows per tick. The strips and one copy of every
 * belt model per strip are generated by tools/asset-scripts/make_belt_models.py from the table below, for both
 * directions (positive: the picture moves towards decreasing v, as Create's positive scroll does).
 * <p>
 * Create's speed: the texture loops (16 rows on flat belts, 12 on diagonal ones) once every 504 / rpm ticks, so
 * the rate is rpm * 16 / 504 rows per tick on a flat belt and rpm * 12 / 504 on a diagonal one. The nearest
 * rate of the table is used (in log scale), fast belts use the fastest one (4 rows per tick, since faster
 * shifts of a 16 row loop only look like flickering). A stopped belt uses Create's static texture.
 */
public final class BeltScroll {
	private BeltScroll() {}

	/** {k, f}: rows per frame and ticks per frame. Keep in sync with make_belt_models.py. */
	public static final int[][] RATES = {
		{ 1, 32 }, { 1, 16 }, { 3, 32 }, { 1, 8 }, { 3, 16 }, { 1, 4 }, { 3, 8 },
		{ 1, 2 }, { 3, 4 }, { 1, 1 }, { 3, 2 }, { 2, 1 }, { 3, 1 }, { 4, 1 }
	};

	/** Texture rows per tick for a belt turning at {@code rpm}, before choosing a rate. */
	public static float targetRate(float rpm, boolean diagonal) {
		return Math.abs(rpm) * (diagonal ? 12f : 16f) / 504f;
	}

	/** Index into {@link #RATES} for the belt's speed, or -1 for a stopped belt. */
	public static int rateIndex(float rpm, boolean diagonal) {
		if (rpm == 0)
			return -1;
		double target = targetRate(rpm, diagonal);
		int best = 0;
		double bestError = Double.MAX_VALUE;
		for (int i = 0; i < RATES.length; i++) {
			double rate = (double) RATES[i][0] / RATES[i][1];
			double error = Math.abs(Math.log(target / rate));
			if (error < bestError) {
				bestError = error;
				best = i;
			}
		}
		return best;
	}

	/**
	 * Which way the surface scrolls, as Create's BeltRenderer works it out: true if the (v shifted) texture
	 * moves with a positive scroll.
	 */
	public static boolean positiveScroll(BeltSlope slope, Direction facing, float speed) {
		boolean downward = slope == BeltSlope.DOWNWARD;
		boolean diagonal = slope.isDiagonal();
		boolean sideways = slope == BeltSlope.SIDEWAYS;
		boolean alongX = facing.getAxis() == Direction.Axis.X;
		AxisDirection axisDirection = facing.getAxisDirection();

		if (diagonal && (downward ^ alongX) || !sideways && !diagonal && alongX
			|| sideways && axisDirection == AxisDirection.NEGATIVE)
			speed = -speed;
		return speed * axisDirection.getStep() > 0;
	}

	/** Name of a model with a scrolling texture, relative to models/block. */
	public static String modelPath(String partial, boolean positive, int rateIndex) {
		int[] rate = RATES[rateIndex];
		return "belt_scroll/" + partial + (positive ? "_p" : "_n") + "_r" + rate[0] + "_" + rate[1];
	}

}
